dashboard.definition:
{
	"title": "Authentication and Policy Enforcement",
	"description": "Validate authentication outcomes and verify access policy enforcement.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#16283c",
				"strokeColor": "rgba(53,207,245,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Zero Trust Access",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/zero-trust-access.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e8f1fb",
				"markdown": "# Authentication and Policy Enforcement\nValidate authentication outcomes and verify access policy enforcement."
			}
		},
		"viz_secure_networking_zta_ise_auth_by_device_fail_rate": {
			"type": "splunk.table",
			"title": "ZTA ISE Auth Failure Rate by Network Device",
			"dataSources": {
				"primary": "ds_secure_networking_zta_ise_auth_by_device_fail_rate"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Per- network access device (NAD) ISE authentication failure rate , identifying which switches, WLCs, or VPN concentrators are contributing most to failed authentications and may require investigation."
		},
		"viz_secure_networking_ise_policy_hits_by_device": {
			"type": "splunk.table",
			"title": "ISE Policy Hits by Network Device",
			"dataSources": {
				"primary": "ds_secure_networking_ise_policy_hits_by_device"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Ranks ISE policy-set hits by the network device (site/branch identity, e.g. wireless controller or firewall hostname) that triggered them — the closest real, validated proxy for \"Policy Hits by Site\" available today."
		},
		"viz_secure_networking_infra_ise_device_count": {
			"type": "splunk.singlevalue",
			"title": "Infrastructure ISE Network Device Count",
			"dataSources": {
				"primary": "ds_secure_networking_infra_ise_device_count"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineDisplay": "below",
				"sparklineNullValueDisplay": "connect",
				"trendDisplay": "percent",
				"majorColor": "#53bfff",
				"majorValue": "> primary | seriesByName('ise_device_count') | lastPoint()"
			},
			"description": "Total count of unique network access devices (NADs) enforcing ISE policy , based on distinct device names seen in ISE syslog, providing the Zero Trust enforcement infrastructure footprint KPI."
		},
		"viz_secure_networking_ise_policy_family_overview": {
			"type": "splunk.table",
			"title": "ISE Policy Family Overview",
			"dataSources": {
				"primary": "ds_secure_networking_ise_policy_family_overview"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Breaks down Cisco ISE policy sets by protocol family — RADIUS (network access) vs. TACACS+ (device administration) — showing policy set counts, cumulative hit counts, and enablement state per ISE host."
		},
		"viz_secure_networking_zta_radius_node_health_by_site": {
			"type": "splunk.table",
			"title": "ZTA RADIUS Node Health by Site",
			"dataSources": {
				"primary": "ds_secure_networking_zta_radius_node_health_by_site"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Summarizes ISE/RADIUS control-plane health by ISE host, site, and network device using success/failure mix and last-seen freshness."
		},
		"viz_security_resilience_ise_radius_latency": {
			"type": "splunk.line",
			"title": "ISE RADIUS Request Latency",
			"dataSources": {
				"primary": "ds_security_resilience_ise_radius_latency"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "bottom",
				"seriesColors": [
					"#3B82F6",
					"#10B981",
					"#ff9a4a",
					"#EF4444"
				],
				"dataValuesDisplay": "minmax",
				"legendTruncation": "ellipsisEnd",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "show",
				"yAxisTitleText": "Latency (ms)",
				"lineWidth": 2,
				"markerDisplay": "outlined",
				"nullValueDisplay": "connect"
			},
			"description": "Tracks average RADIUS request processing latency in milliseconds per ISE node, the most direct indicator of authentication performance visible to end users and NADs."
		},
		"viz_secure_networking_zta_duo_admin_activity_by_outcome": {
			"type": "splunk.table",
			"title": "ZTA Duo Admin Activity by Outcome",
			"dataSources": {
				"primary": "ds_secure_networking_zta_duo_admin_activity_by_outcome"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Breaks down Cisco Duo admin-panel activity by action and outcome, showing success vs. non-success counts and distinct admins per action."
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "**Audience:** Identity, NAC, and access-policy operations  •  **Sources:** Cisco ISE RADIUS, policy-set, and network-device telemetry  •  **Reading guide:** Confirm enforcement footprint and latency, then investigate devices and policy hits.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "### Policy enforcement\nConfirm enforcement footprint and latency, then investigate devices and policy hits."
			}
		}
	},
	"dataSources": {
		"ds_secure_networking_zta_ise_auth_by_device_fail_rate": {
			"name": "Secure Networking - ZTA ISE Auth Failure Rate by Network Device",
			"options": {
				"ref": "secure_networking_zta_ise_auth_by_device_fail_rate",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_ise_policy_hits_by_device": {
			"name": "Secure Networking - ISE Policy Hits by Network Device",
			"options": {
				"ref": "secure_networking_ise_policy_hits_by_device",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_infra_ise_device_count": {
			"name": "Secure Networking - Infrastructure ISE Network Device Count",
			"options": {
				"ref": "secure_networking_infra_ise_device_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_ise_policy_family_overview": {
			"name": "Secure Networking - ISE Policy Family Overview",
			"options": {
				"ref": "secure_networking_ise_policy_family_overview",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_zta_radius_node_health_by_site": {
			"name": "Secure Networking - ZTA RADIUS Node Health by Site",
			"options": {
				"ref": "secure_networking_zta_radius_node_health_by_site",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_security_resilience_ise_radius_latency": {
			"name": "Security Resilience - ISE RADIUS Request Latency",
			"options": {
				"ref": "security_resilience_ise_radius_latency",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_zta_duo_admin_activity_by_outcome": {
			"name": "Secure Networking - ZTA Duo Admin Activity by Outcome",
			"options": {
				"ref": "secure_networking_zta_duo_admin_activity_by_outcome",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#07101d",
					"display": "auto-scale",
					"height": 1510,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 88
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 14,
							"w": 56,
							"h": 56
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 108,
							"y": 4,
							"w": 1292,
							"h": 76
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 100,
							"w": 1400,
							"h": 64
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 176,
							"w": 1400,
							"h": 54
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_zta_ise_auth_by_device_fail_rate",
						"position": {
							"x": 20,
							"y": 242,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_ise_policy_hits_by_device",
						"position": {
							"x": 730,
							"y": 242,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_infra_ise_device_count",
						"position": {
							"x": 20,
							"y": 558,
							"w": 690,
							"h": 190
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_ise_policy_family_overview",
						"position": {
							"x": 730,
							"y": 558,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_zta_radius_node_health_by_site",
						"position": {
							"x": 20,
							"y": 874,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_security_resilience_ise_radius_latency",
						"position": {
							"x": 730,
							"y": 874,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_zta_duo_admin_activity_by_outcome",
						"position": {
							"x": 20,
							"y": 1190,
							"w": 690,
							"h": 300
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
